window.ROLES={"nurse":{"label":"Điều dưỡng","emoji":"🩺","scenarios":[{"k":"r_ns_admit","l":"Tiếp nhận bệnh nhân nhập viện","s":"You are a foreign patient being admitted to the ward. I am your nurse. Answer my questions about your name, allergies and current medicine. Ask about visiting hours and the call button."},{"k":"r_ns_pain","l":"Bệnh nhân đau sau mổ","s":"You are a patient on the ward the day after surgery. Tell me you are in pain. Answer my questions about the pain score, and ask if you can have more medicine."},{"k":"r_ns_doctor","l":"Gọi báo bác sĩ","s":"You are the doctor on call. I am a nurse phoning you about a patient whose condition has changed. Ask me clear questions about the patient's vital signs and what I need from you."},{"k":"r_ns_handover","l":"Giao ban cuối ca","s":"You are the nurse starting the next shift. I will hand over my patients. Ask about any changes, pending tests and patients to watch."},{"k":"r_ns_postop","l":"Bệnh nhân vừa mổ xong","s":"You are a patient who has just come back to the ward after an operation. You feel sleepy and a little sick, and you want to get up to use the toilet. I am your nurse."},{"k":"r_ns_isolation","l":"Người nhà vào phòng cách ly","s":"You are a visitor who wants to go into an isolation room quickly without a gown or mask. I am the nurse. Argue a little, then agree if I explain kindly."}],"dialogues":[{"them":"Nurse, can I have more painkillers?","opts":[{"t":"I'll check your chart and ask the doctor. How bad is the pain from 0 to 10?","good":true,"fb":"Không tự ý cho thuốc + kiểm tra y lệnh + đánh giá mức đau."},{"t":"Sure, take two more.","good":false,"fb":"Tự ý cho thêm thuốc khi chưa có y lệnh — không an toàn."},{"t":"No, you take already.","good":false,"fb":"Sai thì ('You've already had some') và cộc lốc."}]},{"them":"Why do you keep asking my name?","opts":[{"t":"Because I forget.","good":false,"fb":"Sai thì và làm bệnh nhân mất tin tưởng."},{"t":"It's for your safety. We check your name before every medicine and test.","good":true,"fb":"Giải thích lý do an toàn một cách nhẹ nhàng."},{"t":"It's rule, just answer.","good":false,"fb":"Thiếu mạo từ ('the rule') và thiếu lịch sự."}]},{"them":"I think I'm allergic to this.","opts":[{"t":"No, it's a normal medicine.","good":false,"fb":"Bỏ qua cảnh báo dị ứng — rất nguy hiểm."},{"t":"You allergy before?","good":false,"fb":"Sai từ loại và cấu trúc: 'Have you had an allergy to it before?'"},{"t":"Thank you for telling me. I won't give it until I've checked with the doctor.","good":true,"fb":"Dừng ngay + kiểm tra với bác sĩ."}]},{"them":"Can I get out of bed by myself?","opts":[{"t":"Not yet, please. Press the call button and I'll help you, so you don't fall.","good":true,"fb":"Hướng dẫn an toàn + lý do + cách gọi hỗ trợ."},{"t":"Yes, no problem.","good":false,"fb":"Bỏ qua nguy cơ té ngã."},{"t":"No! Don't!","good":false,"fb":"Quá gay gắt, thiếu giải thích."}]},{"them":"Doctor: What's his blood pressure?","opts":[{"t":"It's low, quite low.","good":false,"fb":"Không có số cụ thể, bác sĩ khó đánh giá."},{"t":"It's 90 over 60, lower than this morning. His pulse is 110.","good":true,"fb":"Số liệu chính xác + so sánh diễn tiến + thông tin kèm theo."},{"t":"Ninety sixty, I think.","good":false,"fb":"Đọc không rõ ('90 over 60') và thiếu chắc chắn — hãy đo lại nếu chưa chắc."}]},{"them":"How are you today, nurse?","opts":[{"t":"Very tired, too many patients.","good":false,"fb":"Than phiền với bệnh nhân là thiếu chuyên nghiệp."},{"t":"I'm fine. And you are fine?","good":false,"fb":"Sai cấu trúc câu hỏi: 'And how are you?'"},{"t":"I'm fine, thank you. More importantly, how are you feeling this morning?","good":true,"fb":"Đáp lịch sự + chuyển sự chú ý về bệnh nhân."}]},{"them":"Can you take this bandage off? It's itchy.","opts":[{"t":"I'm sorry it's itchy. Please try not to scratch it. Let me take a look, and I'll ask the doctor if we can change it.","good":true,"fb":"Đồng cảm + dặn không gãi + kiểm tra + hỏi bác sĩ."},{"t":"OK, I take off now.","good":false,"fb":"Tự ý tháo băng khi chưa có chỉ định; thiếu 'will' và tân ngữ ('I'll take it off')."},{"t":"Itchy is good, mean healing.","good":false,"fb":"Thiếu chủ ngữ/động từ ('It means it's healing') và tự kết luận."}]},{"them":"My father pulled out his drip. He's confused.","opts":[{"t":"Why you let him do that?","good":false,"fb":"Trách người nhà; sai cấu trúc câu hỏi ('Why did you let him…?')."},{"t":"Thank you for telling me. I'm coming now. I'll stop the bleeding, check that he's safe and then tell the doctor.","good":true,"fb":"Đến ngay + điều dưỡng tự cầm máu, kiểm tra an toàn người bệnh + báo bác sĩ."},{"t":"No problem, I put again later.","good":false,"fb":"Chậm xử lý; thiếu 'will' và tân ngữ ('I'll put it back')."}]},{"them":"I don't want the injection. I'm scared of needles.","opts":[{"t":"You must have it, doctor said.","good":false,"fb":"Ép buộc — người bệnh có quyền được giải thích và từ chối; thiếu mạo từ ('the doctor')."},{"t":"Needle small, not hurt.","good":false,"fb":"Thiếu động từ ('It's a small needle') và hứa không đau là không trung thực."},{"t":"It's OK to feel scared. Can you tell me what worries you? I'll explain why the doctor ordered it, and then you can decide.","good":true,"fb":"Công nhận cảm xúc + giải thích + tôn trọng quyền quyết định của người bệnh."}]},{"them":"Can you tell me my blood test results?","opts":[{"t":"The doctor will go through them with you on the ward round this morning. I'll remind her that you're waiting.","good":true,"fb":"Không tự giải thích kết quả + nói khi nào bác sĩ báo + nhắc bác sĩ giúp."},{"t":"I saw them. Your sugar a bit high.","good":false,"fb":"Thiếu 'is' và điều dưỡng không nên tự giải thích kết quả thay bác sĩ."},{"t":"Not my job, sorry.","good":false,"fb":"Đẩy trách nhiệm; nên cho biết khi nào bác sĩ sẽ báo kết quả."}]}]},"reception":{"label":"Lễ tân phòng khám","emoji":"🗂️","scenarios":[{"k":"r_rc_new","l":"Đăng ký bệnh nhân mới","s":"You are a foreign patient visiting the clinic for the first time with a sore throat. I am the receptionist. Give your details when I ask, and ask how long you will wait."},{"k":"r_rc_book","l":"Đặt lịch qua điện thoại","s":"You are calling the clinic to book an appointment with a skin specialist next week. Ask about available times, the price and what to bring."},{"k":"r_rc_insurance","l":"Hỏi về bảo hiểm","s":"You are an expat patient with international health insurance. Ask if the clinic can bill your insurance directly and what you need to pay today."},{"k":"r_rc_wait","l":"Bệnh nhân chờ lâu","s":"You are a patient who has waited 90 minutes. Complain politely but firmly. Calm down if I apologise and tell you exactly what will happen next."},{"k":"r_rc_child","l":"Phụ huynh gọi vì con sốt","s":"You are a parent calling the clinic because your 2-year-old has had a fever since last night. I am the receptionist. Ask if you can come today and what to bring."},{"k":"r_rc_followup","l":"Đặt lịch tái khám sau ra viện","s":"You are a patient who left hospital last week. Call the clinic to book a follow-up appointment and ask for a copy of your discharge summary."}],"dialogues":[{"them":"Hello, I'd like to book an appointment.","opts":[{"t":"Book when?","good":false,"fb":"Cụt lủn, thiếu lịch sự."},{"t":"Of course. Which doctor would you like to see, and what day suits you?","good":true,"fb":"Đồng ý + hỏi hai thông tin cần để đặt lịch."},{"t":"OK, what is your problem?","good":false,"fb":"Hỏi sức khỏe qua điện thoại chung chung nghe đột ngột; nên hỏi bác sĩ/thời gian trước."}]},{"them":"How much is a consultation?","opts":[{"t":"Not expensive, don't worry.","good":false,"fb":"Không cho con số cụ thể."},{"t":"Consultation is 500 thousands.","good":false,"fb":"Sai: 'five hundred thousand' không có 's'; nên nói kèm đơn vị 'dong'."},{"t":"It's 500,000 dong with a general doctor. Tests are charged separately.","good":true,"fb":"Giá rõ + lưu ý chi phí phát sinh."}]},{"them":"Can I see the doctor now? It's urgent.","opts":[{"t":"I'm sorry you're not feeling well. Can you tell me briefly what's wrong? I'll ask the nurse to see you straight away.","good":true,"fb":"Đồng cảm + hỏi ngắn + chuyển điều dưỡng đánh giá mức khẩn."},{"t":"Everyone is urgent. Please wait.","good":false,"fb":"Gạt đi — lễ tân không được tự đánh giá mức khẩn."},{"t":"You wait, number 30.","good":false,"fb":"Cộc lốc, bỏ qua mức độ khẩn."}]},{"them":"What do I need to bring tomorrow?","opts":[{"t":"Bring everything.","good":false,"fb":"Mơ hồ, bệnh nhân không biết mang gì."},{"t":"Please bring your passport, your insurance card and any medicine you're taking.","good":true,"fb":"Liệt kê đầy đủ, rõ ràng."},{"t":"You bring passport and insurance.","good":false,"fb":"Thiếu 'Please' và 'your', nghe như ra lệnh."}]},{"them":"Can I change my appointment to Friday?","opts":[{"t":"Friday full already.","good":false,"fb":"Thiếu 'is' và chưa kiểm tra kỹ."},{"t":"Yes, you come Friday.","good":false,"fb":"Chưa nêu giờ cụ thể, dễ gây nhầm lịch."},{"t":"Let me check. Yes, Dr Anna has a free slot at 10 a.m. on Friday. Shall I book it?","good":true,"fb":"Kiểm tra + phương án cụ thể + hỏi xác nhận."}]},{"them":"Can you tell me my wife's test results?","opts":[{"t":"I'm sorry, I can only share results with the patient. The doctor can talk to her, or to you if she agrees.","good":true,"fb":"Bảo mật thông tin bệnh nhân + giải thích lịch sự."},{"t":"Sure, she is your wife, no problem.","good":false,"fb":"Vi phạm bảo mật thông tin bệnh nhân."},{"t":"No, it's secret.","good":false,"fb":"Đúng nguyên tắc nhưng quá cộc, không đưa hướng giải quyết."}]},{"them":"Do I need to bring my son's vaccination book?","opts":[{"t":"Yes, bring book.","good":false,"fb":"Câu cụt, thiếu 'please' và 'his'."},{"t":"Yes, please. The nurse will check which vaccinations he's had.","good":true,"fb":"Xác nhận + lý do rõ ràng."},{"t":"Book not important.","good":false,"fb":"Sai thông tin và thiếu động từ ('isn't')."}]},{"them":"My baby is only three months old and has a fever. Can we come now?","opts":[{"t":"Next appointment is Friday.","good":false,"fb":"Hẹn muộn với trẻ nhỏ đang sốt là không an toàn."},{"t":"Give baby medicine and wait.","good":false,"fb":"Lễ tân không được khuyên dùng thuốc qua điện thoại."},{"t":"Yes, please come now. I'll tell the nurse you're coming so she can see your baby first.","good":true,"fb":"Không hẹn muộn — trẻ nhỏ như vậy bị sốt cần được xem ngay; báo điều dưỡng ưu tiên."}]},{"them":"I left hospital last week. Can I have a copy of my discharge summary?","opts":[{"t":"Of course. May I see your ID first? Then I'll print a copy for you.","good":true,"fb":"Xác minh danh tính trước khi đưa hồ sơ + đáp ứng yêu cầu."},{"t":"Sure, what name? I print now.","good":false,"fb":"Không xác minh danh tính; thiếu 'will' ('I'll print it')."},{"t":"No, you already have it.","good":false,"fb":"Từ chối không lý do — người bệnh có quyền xin bản sao hồ sơ của mình."}]},{"them":"Is there a female doctor for children? My daughter is shy.","opts":[{"t":"Doctor is doctor, no matter.","good":false,"fb":"Gạt bỏ mong muốn chính đáng của phụ huynh."},{"t":"Let me check. Dr Anna is free at 3 p.m. today. Would you like me to book her?","good":true,"fb":"Tôn trọng mong muốn + kiểm tra + đưa lựa chọn cụ thể."},{"t":"Woman doctor not have today.","good":false,"fb":"Dịch từng chữ: 'There's no female doctor today.'"}]}]},"pharmacy":{"label":"Nhà thuốc · Dược","emoji":"💊","scenarios":[{"k":"r_ph_rx","l":"Nhận đơn thuốc","s":"You are a foreign customer bringing a prescription to the pharmacy. I am the pharmacy staff. Answer my questions about allergies and other medicine, and ask how to take it."},{"k":"r_ph_otc","l":"Hỏi mua thuốc không kê đơn","s":"You are a tourist with a cold asking for something to help. I am the pharmacy staff. Answer my questions. Ask for antibiotics, and accept my advice if I explain politely."},{"k":"r_ph_side","l":"Phản ánh tác dụng phụ","s":"You are a customer who bought medicine yesterday and now feels a little sick. Ask me if you should stop taking it."},{"k":"r_ph_stock","l":"Thuốc hết hàng","s":"You are a customer whose regular medicine is out of stock at the pharmacy. Ask what you can do and when it will arrive."},{"k":"r_ph_child","l":"Mua thuốc cho trẻ em","s":"You are a parent asking for fever medicine for your 4-year-old. I am the pharmacy staff. Answer my questions about her age, weight and allergies, and ask how much to give."},{"k":"r_ph_refill","l":"Hết thuốc dùng lâu dài","s":"You are an expat who has run out of your regular blood pressure medicine and has no new prescription. Ask me to sell you more, and accept my advice if I explain kindly."}],"dialogues":[{"them":"Here's my prescription.","opts":[{"t":"OK, wait.","good":false,"fb":"Cộc và bỏ qua bước hỏi dị ứng."},{"t":"Thank. You sit.","good":false,"fb":"Thiếu 's' và câu mệnh lệnh cụt."},{"t":"Thank you. Before I prepare it, are you allergic to any medicine?","good":true,"fb":"Cảm ơn + hỏi dị ứng trước khi soạn thuốc."}]},{"them":"Can I take this with alcohol?","opts":[{"t":"Let me check that with the pharmacist for you. Some medicines don't mix well with alcohol.","good":true,"fb":"Không đoán + hỏi dược sĩ + nhắc chung về rủi ro khi uống rượu bia."},{"t":"A little beer is OK.","good":false,"fb":"Khuyên sai, có thể gây hại."},{"t":"Why you drink when sick?","good":false,"fb":"Sai cấu trúc câu hỏi và mang tính phán xét."}]},{"them":"How many times a day should I take this?","opts":[{"t":"Take when you feel bad.","good":false,"fb":"Tự đặt cách dùng, không theo đơn."},{"t":"It's written on the label, as your doctor prescribed. Let me go through it with you.","good":true,"fb":"Dựa vào đơn/nhãn + hướng dẫn cùng bệnh nhân."},{"t":"Many times is better.","good":false,"fb":"Nguy hiểm — khuyến khích dùng quá liều."}]},{"them":"Do you have something for a headache?","opts":[{"t":"Yes, this one, very strong.","good":false,"fb":"Không hỏi thông tin an toàn trước khi bán."},{"t":"Headache is normal, drink water.","good":false,"fb":"Coi nhẹ triệu chứng, không tư vấn."},{"t":"Before I suggest anything, do you have any allergies, or are you taking any other medicine?","good":true,"fb":"Hỏi dị ứng và thuốc đang dùng trước khi gợi ý thuốc."}]},{"them":"This medicine is out of stock? I need it today.","opts":[{"t":"I'm sorry. Our other branch has it. I can call them and ask them to keep one for you.","good":true,"fb":"Xin lỗi + giải pháp cụ thể."},{"t":"No have, sorry.","good":false,"fb":"Dịch từng chữ: 'Sorry, we don't have it.' — và thiếu giải pháp."},{"t":"Take another medicine, same same.","good":false,"fb":"Tự ý đổi thuốc kê đơn là không an toàn."}]},{"them":"Is this medicine safe during pregnancy?","opts":[{"t":"Yes, it's safe, I think.","good":false,"fb":"Đoán mò về vấn đề an toàn thai kỳ."},{"t":"That's an important question. Please check with your doctor or our pharmacist before taking it.","good":true,"fb":"Ghi nhận + chuyển đúng chuyên môn."},{"t":"I don't know, you search online.","good":false,"fb":"Thiếu trách nhiệm và thiếu lịch sự — vấn đề an toàn phải hỏi chuyên môn."}]},{"them":"How much of this syrup should I give my daughter?","opts":[{"t":"One big spoon, like adult.","good":false,"fb":"Nguy hiểm — liều trẻ em khác người lớn."},{"t":"Give when she cry.","good":false,"fb":"Sai chia ('cries') và không hướng dẫn theo nhãn."},{"t":"For children, it depends on age and weight. May I ask how much she weighs? The pharmacist will then go through the label with you.","good":true,"fb":"Không tự đưa liều + liều trẻ em tính theo tuổi/cân nặng + dược sĩ hướng dẫn."}]},{"them":"I've run out of my blood pressure tablets. Can I buy more without a prescription?","opts":[{"t":"I'm sorry, we need a prescription for this medicine. There's a clinic next door, and they can see you today.","good":true,"fb":"Tuân thủ quy định + hướng giải quyết ngay trong ngày."},{"t":"Sure, how many boxes?","good":false,"fb":"Bán thuốc kê đơn khi không có đơn là sai quy định."},{"t":"No prescription, you stop the medicine.","good":false,"fb":"Khuyên ngừng thuốc huyết áp là nguy hiểm."}]},{"them":"Can I give my son my own cough medicine?","opts":[{"t":"Yes, half is OK for kids.","good":false,"fb":"Nguy hiểm — không tự chia liều thuốc người lớn cho trẻ."},{"t":"Please don't. Some adult medicines aren't safe for children. Let me ask you a few questions, and the pharmacist can suggest something for his age.","good":true,"fb":"Cảnh báo an toàn + hỏi thông tin + để dược sĩ tư vấn."},{"t":"Cough medicine all same.","good":false,"fb":"Thiếu động từ ('are all the same') và sai thông tin."}]},{"them":"Do you have gloves and hand sanitiser?","opts":[{"t":"Have, over there.","good":false,"fb":"Thiếu chủ ngữ và tân ngữ: 'Yes, we have them.'"},{"t":"Sanitiser finish already.","good":false,"fb":"Dịch từng chữ 'hết rồi': 'Sorry, we've run out of sanitiser.'"},{"t":"Yes, they're in aisle two, next to the masks. I'll show you.","good":true,"fb":"Chỉ vị trí cụ thể + đề nghị dẫn đi."}]}]},"care":{"label":"Chăm sóc · Hộ lý","emoji":"🤝","scenarios":[{"k":"r_cr_morning","l":"Chăm sóc buổi sáng","s":"You are an elderly foreign patient in a care home. I am your care assistant helping you in the morning. Ask for help with washing and breakfast, and say you feel a bit weak."},{"k":"r_cr_family","l":"Người nhà hỏi thăm","s":"You are the daughter of an elderly patient. Ask me how your mother ate and slept, and ask when you can talk to the nurse."},{"k":"r_cr_refuse","l":"Bệnh nhân không chịu ăn","s":"You are an elderly patient who doesn't want to eat lunch because you feel sad. Open up only if I am patient and kind."},{"k":"r_cr_move","l":"Hỗ trợ di chuyển","s":"You are a patient who needs help moving from the bed to a wheelchair. Tell me you are afraid of falling."},{"k":"r_cr_dementia","l":"Người sa sút trí tuệ đòi về nhà","s":"You are an elderly resident with dementia who keeps asking to go home to see your mother. I am your carer. Stay upset unless I am calm, kind and gently change the topic."},{"k":"r_cr_meal","l":"Hỗ trợ bữa ăn","s":"You are an elderly patient with swallowing problems. I am helping you eat lunch. Say the food is too thick, and cough once while drinking."}],"dialogues":[{"them":"I don't feel like eating today.","opts":[{"t":"That's OK. Would you like something small, like soup or fruit? I'll also tell the nurse.","good":true,"fb":"Tôn trọng + gợi ý nhẹ nhàng + báo điều dưỡng."},{"t":"You must eat, eat now.","good":false,"fb":"Ép buộc, thiếu tôn trọng người bệnh."},{"t":"Why you don't eat?","good":false,"fb":"Sai cấu trúc câu hỏi: 'Why don't you want to eat?'"}]},{"them":"Can you help me get into the wheelchair?","opts":[{"t":"OK, jump in.","good":false,"fb":"Không an toàn, dễ gây ngã."},{"t":"Of course. Let me lock the brakes first. Hold my arm and stand up slowly with me.","good":true,"fb":"An toàn trước (khóa phanh) + hướng dẫn từng bước."},{"t":"You can do yourself.","good":false,"fb":"Thiếu 'it by' ('do it by yourself') và từ chối hỗ trợ."}]},{"them":"How did my mother sleep last night?","opts":[{"t":"She sleep good.","good":false,"fb":"Sai thì và từ loại: 'She slept well.'"},{"t":"I don't know, not my shift.","good":false,"fb":"Nên nói 'Let me check the notes for you.'"},{"t":"She slept quite well and woke up once. The nurse can tell you more about her health.","good":true,"fb":"Thông tin trong phạm vi quan sát + chuyển điều dưỡng về chuyên môn."}]},{"them":"I feel a bit dizzy.","opts":[{"t":"Please sit down and stay here. I'll call the nurse right now.","good":true,"fb":"Giữ an toàn + báo ngay điều dưỡng."},{"t":"Walk a little, you will feel better.","good":false,"fb":"Nguy cơ té ngã khi đang chóng mặt."},{"t":"It's normal for old people.","good":false,"fb":"Coi nhẹ triệu chứng và mang tính định kiến tuổi tác."}]},{"them":"I want to wash by myself.","opts":[{"t":"No, you are too old.","good":false,"fb":"Thiếu tôn trọng, định kiến tuổi tác."},{"t":"Of course. I'll wait outside. Please use the handrail and call me if you need anything.","good":true,"fb":"Tôn trọng sự tự chủ + nhắc an toàn."},{"t":"OK, you wash, I go.","good":false,"fb":"Câu cụt; bỏ đi mà không dặn an toàn."}]},{"them":"Can you open the window? It's hot.","opts":[{"t":"Hot? I feel cold.","good":false,"fb":"Lấy cảm giác của mình phủ nhận nhu cầu người bệnh."},{"t":"Wait, I open.","good":false,"fb":"Thiếu 'will' và tân ngữ: 'I'll open it.'"},{"t":"Sure. Is that better? I can also bring you some water.","good":true,"fb":"Đáp ứng + hỏi lại + chăm sóc thêm."}]},{"them":"Can you take my dentures out? They hurt.","opts":[{"t":"Of course. Let me help you take them out, and I'll check your mouth for any sore spots. I'll tell the nurse too.","good":true,"fb":"Đáp ứng + kiểm tra miệng + báo điều dưỡng."},{"t":"Dentures always hurt, is normal.","good":false,"fb":"Thiếu chủ ngữ ('it's normal') và coi nhẹ lời than phiền."},{"t":"You take out yourself.","good":false,"fb":"Thiếu tân ngữ ('take them out') và bỏ mặc người bệnh."}]},{"them":"I've had an accident. I'm so embarrassed.","opts":[{"t":"Again? Why you not call me?","good":false,"fb":"Trách móc; sai cấu trúc câu hỏi ('Why didn't you call me?')."},{"t":"It's OK, please don't worry. It happens. I'll close the curtain and help you get clean and comfortable.","good":true,"fb":"Giữ thể diện + riêng tư + hỗ trợ ngay."},{"t":"Next time wear diaper.","good":false,"fb":"Thiếu mạo từ và làm người cao tuổi xấu hổ thêm."}]},{"them":"Can I go for a walk outside?","opts":[{"t":"Outside is dangerous, stay here.","good":false,"fb":"Hạn chế không cần thiết, thiếu tôn trọng."},{"t":"OK, you go, I busy.","good":false,"fb":"Thiếu 'am' và để người có nguy cơ ngã đi một mình."},{"t":"Of course. Let's get your walking frame and your jacket. I'll walk with you.","good":true,"fb":"Đáp ứng + chuẩn bị dụng cụ + đi cùng để phòng ngã."}]},{"them":"I don't like that new medicine. Can you throw it away?","opts":[{"t":"I understand. I can't throw it away, but I'll tell the nurse how you feel, and she can talk to the doctor.","good":true,"fb":"Tôn trọng ý kiến + đúng phạm vi của hộ lý + chuyển điều dưỡng."},{"t":"OK, I throw away for you.","good":false,"fb":"Tự ý bỏ thuốc là vi phạm an toàn; thiếu 'will' và tân ngữ."},{"t":"You must take, no choice.","good":false,"fb":"Ép buộc, thiếu tân ngữ ('take it') và không lắng nghe."}]}]}};
